style.css:
@-moz-document domain("centralgraphics-cg.com") {
/* Fondo blanco a gris oscuro */
  * {
    background-color: rgba(33, 33, 33, 1) !important;
  }

  /* Texto gris (rgba(144,144,144,1)) a blanco */
  * {
    color: #ffffff !important;
  }

  /* Reemplazo de imagen icon_menu.jpg por nueva URL */
  img[src*="icon_menu.jpg"] {
    content: url("https://i.postimg.cc/x1w7kd7J/menu-icons.png") !important;
  }

  /* También si se usa como background */
  [style*="icon_menu.jpg"] {
    background-image: url("https://i.postimg.cc/x1w7kd7J/menu-icons.png") !important;
  }

  /* Forzar contraste en enlaces */
  a, a * {
    color: #ffffff !important;
  }

  /* Inputs oscuros */
  input, textarea, select {
    background-color: #222 !important;
    color: #fff !important;
    border-color: #444 !important;
  }
}
